def get(self, key, default=None):
    p = self._path(key)
    if not os.path.exists(p):
        return default
    with open(p) as f:
        rec = json.load(f)

    # An entry is valid only for ``ttl`` seconds after it was written.
    # Remove expired entries so that a cache miss also cleans up disk.
    if self._now() - rec["t"] > self.ttl:
        try:
            os.remove(p)
        except FileNotFoundError:
            # Another reader may have cleaned it up already.
            pass
        return default
    return rec["v"]
